/* ======================================================================== */
/*  pictures: top screen = 256x192 8-bit bitmap background                  */
/* ======================================================================== */
static int bg_id = -1;
static u8 small[128 * 96];

void gfx_init(void) {
    videoSetMode(MODE_5_2D);
    vramSetBankA(VRAM_A_MAIN_BG);
    bg_id = bgInit(3, BgType_Bmp8, BgSize_B8_256x256, 0, 0);
}

void gfx_show(int scene) {
    if (bg_id < 0 || scene < 0 || scene >= GFX_SCENE_COUNT) return;
    const GfxImage *im = &images[scene];

    /* 1) unpack the run-length data into a 128x96 image in normal RAM */
    u32 o = 0;
    for (u32 i = 0; i + 1 < im->rle_len; i += 2) {
        u32 n = im->rle[i];
        u8 v = im->rle[i + 1];
        while (n > 0 && o < 128 * 96) {
            small[o++] = v;
            n--;
        }
    }

    for (u32 i = 0; i < im->pal_count; i++) BG_PALETTE[i] = im->pal[i];

    /* 2) blow it up 2x into video memory (16 bits at a time = 2 pixels) */
    u16 *dst = (u16 *)bgGetGfxPtr(bg_id);
    for (u32 y = 0; y < 96; y++) {
        u16 *row0 = dst + (y * 2) * 128;
        u16 *row1 = row0 + 128;
        const u8 *src = small + y * 128;
        for (u32 x = 0; x < 128; x++) {
            u16 v = src[x];
            u16 two = (u16)(v | (v << 8));
            row0[x] = two;
            row1[x] = two;
        }
    }
}

int gfx_princess_x(int scene) {
    if (scene < 0 || scene >= GFX_SCENE_COUNT) return 128;
    return princess_x_tbl[scene];
}

/* ======================================================================== */
/*  effects: fades, flash and sparkle / heart / coin particles (sprites)    */
/* ======================================================================== */
#define MAX_P 32

typedef struct {
    s32 x, y;      /* 24.8 fixed point, screen pixels */
    s32 vx, vy;
    s16 life;
    u8 kind;       /* 0 yellow sparkle, 1 heart, 2 coin, 3 blue sparkle */
    u8 mode;       /* 0 float up, 1 twinkle in place, 2 rain down */
    bool on;
} Particle;

static Particle ps[MAX_P];
static u16 *tile_gfx[3];
static u32 rng_state = 12345;
static u32 frame_count = 0;

/* 8x8 shapes, 4 bits per pixel: '.' = clear, 1/2/3 = palette colours */
static const char *const shapes[3][8] = {
    { "...11...", "...11...", "..1221..", "11122111",
      "11122111", "..1221..", "...11...", "...11..." },          /* sparkle */
    { ".11..11.", "12111111", "11111111", "11111111",
      ".111111.", "..1111..", "...11...", "........" },          /* heart   */
    { "..3333..", ".311113.", "31122113", "31211113",
      "31111113", "31111113", ".311113.", "..3333.." },          /* coin    */
};
static const u8 kind_shape[4] = { 0, 1, 2, 0 };
static const u8 pal_rgb[4][3][3] = {
    { { 255, 226,  90 }, { 255, 255, 255 }, {   0,   0,   0 } },
    { { 255, 110, 160 }, { 255, 200, 220 }, { 200,  60, 110 } },
    { { 250, 200,  60 }, { 255, 246, 170 }, { 190, 130,  30 } },
    { { 120, 190, 255 }, { 255, 255, 255 }, {   0,   0,   0 } },
};

static int rnd(int n) {
    rng_state = rng_state * 1664525u + 1013904223u;
    return (int)((rng_state >> 16) % (u32)n);
}

static Particle *alloc_particle(void) {
    for (int i = 0; i < MAX_P; i++) {
        if (!ps[i].on) return &ps[i];
    }
    return 0;
}

void fx_init(void) {
    vramSetBankB(VRAM_B_MAIN_SPRITE);
    oamInit(&oamMain, SpriteMapping_1D_32, false);
    REG_DISPCNT |= DISPLAY_SPR_ACTIVE;

    for (int s = 0; s < 3; s++) {
        tile_gfx[s] = oamAllocateGfx(&oamMain, SpriteSize_8x8, SpriteColorFormat_16Color);
        for (int r = 0; r < 8; r++) {
            for (int h = 0; h < 2; h++) {
                u16 w = 0;
                for (int k = 0; k < 4; k++) {
                    char c = shapes[s][r][h * 4 + k];
                    u16 v = (c == '.') ? 0 : (u16)(c - '0');
                    w |= (u16)(v << (4 * k));
                }
                tile_gfx[s][r * 2 + h] = w;
            }
        }
    }
    for (int p = 0; p < 4; p++) {
        for (int i = 0; i < 3; i++) {
            SPRITE_PALETTE[p * 16 + 1 + i] =
                RGB15(pal_rgb[p][i][0] >> 3, pal_rgb[p][i][1] >> 3, pal_rgb[p][i][2] >> 3);
        }
    }
    for (int i = 0; i < MAX_P; i++) ps[i].on = false;
}

static void update_particles(void) {
    frame_count++;
    for (int i = 0; i < MAX_P; i++) {
        Particle *p = &ps[i];
        if (p->on) {
            p->x += p->vx;
            p->y += p->vy;
            p->life--;
            if (p->life <= 0 || (p->y >> 8) > 200 || (p->y >> 8) < -16) p->on = false;
        }
        bool visible = p->on && (p->mode != 1 || (p->life % 8) < 5);
        oamSet(&oamMain, i, (int)(p->x >> 8), (int)(p->y >> 8), 0, p->kind == 3 ? 3 : p->kind,
               SpriteSize_8x8, SpriteColorFormat_16Color, tile_gfx[kind_shape[p->kind]],
               -1, false, !visible, false, false, false);
    }
}

/* one frame: move the particles, wait for the screen refresh, push sprites */
void fx_frame(void) {
    update_particles();
    swiWaitForVBlank();
    oamUpdate(&oamMain);
}

void fx_fade_out(int screens, int frames) {
    for (int i = 1; i <= frames; i++) {
        setBrightness(screens, -(16 * i) / frames);
        fx_frame();
    }
}

void fx_fade_in(int screens, int frames) {
    for (int i = frames - 1; i >= 0; i--) {
        setBrightness(screens, -(16 * i) / frames);
        fx_frame();
    }
    setBrightness(screens, 0);
}

void fx_flash(int screens, int frames) {
    for (int i = frames; i >= 0; i--) {
        setBrightness(screens, (12 * i) / frames);
        fx_frame();
    }
    setBrightness(screens, 0);
}

void fx_burst(int kind, int x, int y, int count) {
    for (int k = 0; k < count; k++) {
        Particle *p = alloc_particle();
        if (!p) return;
        p->on = true;
        p->kind = (u8)kind;
        p->mode = 0;
        p->x = (s32)(x + rnd(36) - 18) << 8;
        p->y = (s32)(y + rnd(14) - 7) << 8;
        p->vx = rnd(321) - 160;
        p->vy = -(70 + rnd(230));
        p->life = (s16)(30 + rnd(26));
    }
}

void fx_sparkle_at(int x, int y) {
    Particle *p = alloc_particle();
    if (!p) return;
    p->on = true;
    p->kind = (u8)(rnd(2) ? 0 : 3);
    p->mode = 1;
    p->x = (s32)(x + rnd(61) - 30) << 8;
    p->y = (s32)(y - rnd(90)) << 8;
    p->vx = 0;
    p->vy = 0;
    p->life = 26;
}

/* twinkling stars all over the top screen; call once per frame */
void fx_twinkle(int every) {
    if (every < 1 || (frame_count % (u32)every) != 0) return;
    Particle *p = alloc_particle();
    if (!p) return;
    p->on = true;
    p->kind = (u8)(rnd(2) ? 0 : 3);
    p->mode = 1;
    p->x = (s32)(8 + rnd(240)) << 8;
    p->y = (s32)(8 + rnd(160)) << 8;
    p->vx = 0;
    p->vy = 0;
    p->life = 24;
}

/* sparkles and hearts falling from the top; call once per frame */
void fx_rain(void) {
    if ((frame_count % 5) != 0) return;
    Particle *p = alloc_particle();
    if (!p) return;
    int r = rnd(3);
    p->on = true;
    p->kind = (u8)(r == 0 ? 0 : (r == 1 ? 1 : 3));
    p->mode = 2;
    p->x = (s32)(rnd(248)) << 8;
    p->y = -6 * 256;
    p->vx = rnd(121) - 60;
    p->vy = 150 + rnd(200);
    p->life = 140;
}
